#include <iostream>
#include <algorithm>
#include <map>

int main() {
    int n, m;
    std::cin >> n >> m;
    if (n > m) std::swap(n, m);
    int c;
    if (n == 1) {
        c = std::min(m % 6, 6 - m % 6);
    } else if (n == 2) {
        std::map<int, int> lookup = {{2, 4}, {3, 2}, {7, 2}};
        auto it = lookup.find(m);
        c = (it != lookup.end()) ? it->second : 0;
    } else {
        c = (n & 1) * (m & 1);
    }
    std::cout << n * m - c << std::endl;
    return 0;
}
